/**
 * Generates Material 3 color tokens (light + dark) from a single seed color
 * and writes them to src/app/m3-tokens.css.
 *
 * Usage:
 *   npm run theme                    # regenerate with the SEED below
 *   SEED=#6750A4 npm run theme       # generate from another color
 *
 * Do not edit m3-tokens.css by hand — rerun this script instead.
 */
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  argbFromHex,
  Hct,
  SchemeNeutral,
  hexFromArgb,
} from "@material/material-color-utilities";

// The one place to change the theme color. Neutral grey by default.
const SEED = process.env.SEED ?? "#757575";

// Material 3 color roles (see material_theme_guide.md).
const ROLES = [
  "primary",
  "onPrimary",
  "primaryContainer",
  "onPrimaryContainer",
  "secondary",
  "onSecondary",
  "secondaryContainer",
  "onSecondaryContainer",
  "tertiary",
  "onTertiary",
  "tertiaryContainer",
  "onTertiaryContainer",
  "error",
  "onError",
  "errorContainer",
  "onErrorContainer",
  "surface",
  "onSurface",
  "onSurfaceVariant",
  "surfaceDim",
  "surfaceBright",
  "surfaceContainerLowest",
  "surfaceContainerLow",
  "surfaceContainer",
  "surfaceContainerHigh",
  "surfaceContainerHighest",
  "outline",
  "outlineVariant",
  "inverseSurface",
  "inverseOnSurface",
  "inversePrimary",
  "shadow",
  "scrim",
] as const;

type DynamicColor = { getHct(scheme: SchemeLike): { toInt(): number } };
type SchemeLike = { colors: Record<string, () => DynamicColor> };
type SchemeCtor = new (source: Hct, isDark: boolean, contrastLevel: number) => SchemeLike;

function kebab(s: string): string {
  return s.replace(/[A-Z]/g, (m) => `-${m.toLowerCase()}`);
}

const source = Hct.fromInt(argbFromHex(SEED));
const Neutral = SchemeNeutral as unknown as SchemeCtor;
const light = new Neutral(source, false, 0);
const dark = new Neutral(source, true, 0);

function resolve(scheme: SchemeLike, role: string): string {
  const factory = scheme.colors[role];
  if (typeof factory !== "function") throw new Error(`Unknown M3 role: ${role}`);
  return hexFromArgb(factory().getHct(scheme).toInt());
}

function block(scheme: SchemeLike): string {
  return ROLES.map(
    (role) => `  --md-sys-color-${kebab(role)}: ${resolve(scheme, role)};`,
  ).join("\n");
}

const css = `/* AUTO-GENERATED by scripts/m3-theme.ts — do not edit by hand.
 * Seed: ${SEED} (Material 3 Neutral scheme)
 * Regenerate: npm run theme
 */
:root {
${block(light)}
}

:root:where(.dark) {
${block(dark)}
}
`;

const out = join(dirname(fileURLToPath(import.meta.url)), "..", "src", "app", "m3-tokens.css");
writeFileSync(out, css);
console.log(`Wrote ${out} (seed ${SEED})`);
